document.addEventListener("DOMContentLoaded",()=>{const o=window.location.pathname.split("/").filter(Boolean),l=o[0]||"index",s=(o[o.length-1]||"index").replace(".html","")||"index";document.querySelectorAll(".nav-link, .nav-dropdown-item").forEach(e=>{const t=e.getAttribute("data-page");(t===s||t===l)&&e.classList.add("active")}),["calculator","loan-calculator","loan-comparison","deposit-calculator","inflation-calculator"].includes(s)&&document.querySelector('.nav-dropdown-toggle[data-page="calculators"]')?.classList.add("active");const n=document.querySelector(".mobile-menu-toggle"),a=document.getElementById("site-nav-links");if(!n||!a)return;const c=()=>{a.classList.remove("open"),n.classList.remove("open"),n.setAttribute("aria-expanded","false")};n.addEventListener("click",()=>{const e=a.classList.toggle("open");n.classList.toggle("open",e),n.setAttribute("aria-expanded",String(e))}),document.querySelectorAll(".nav-dropdown-toggle").forEach(e=>{e.addEventListener("click",t=>{t.stopPropagation();const i=e.closest(".nav-dropdown")?.classList.toggle("open");e.setAttribute("aria-expanded",String(!!i))})}),a.querySelectorAll("a").forEach(e=>e.addEventListener("click",c)),document.addEventListener("click",e=>{document.querySelectorAll(".nav-dropdown.open").forEach(t=>{t.contains(e.target)||(t.classList.remove("open"),t.querySelector(".nav-dropdown-toggle")?.setAttribute("aria-expanded","false"))}),e.target.closest(".site-nav")||c()})});
